import {Share} from 'react-native';
import RNFS from 'react-native-fs';
import FileViewer from 'react-native-file-viewer';
import QRCode from 'qrcode';
import RNShare from 'react-native-share';
import {
  TextEncoder as RNTextEncoder,
  TextDecoder as RNTextDecoder,
} from 'text-encoding';
import {getStateName} from './gstCalculations';
import {INVOICE_TEMPLATE_HTML} from './invoiceTemplate';
import {extractInvoiceSequenceNumber} from './invoiceNumber';

const RNHTMLtoPDFModule = require('react-native-html-to-pdf');
const RNHTMLtoPDF = RNHTMLtoPDFModule?.default || RNHTMLtoPDFModule;

if (typeof globalThis.TextEncoder === 'undefined') {
  globalThis.TextEncoder = RNTextEncoder;
  globalThis.TextDecoder = RNTextDecoder;
}

const INVOICE_PDF_DIRECTORY = 'invoices';
const UPI_VPA = '9020411611@upi';
const UPI_NAME = 'OLGA CONCRETE BLOCKS';

function safeString(value: any, fallback = ''): string {
  if (value === null || value === undefined || value === '') {
    return fallback;
  }
  return String(value);
}

function normalizeFileToken(value: any, fallback = ''): string {
  const raw = safeString(value, fallback).trim();
  if (!raw) {
    return fallback;
  }

  const normalized = raw
    .replace(/\s+/g, '_')
    .replace(/[^a-zA-Z0-9_-]/g, '-')
    .replace(/-+/g, '-')
    .replace(/_+/g, '_')
    .replace(/^[-_]+|[-_]+$/g, '');

  return normalized || fallback;
}

function escapeHtml(value: any): string {
  return safeString(value, '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function normalizeDisplayDate(value: any): string {
  const raw = safeString(value, '');
  if (!raw) {
    return '';
  }

  if (/^\d{4}-\d{2}-\d{2}$/.test(raw)) {
    const [year, month, day] = raw.split('-');
    return `${day}-${month}-${year}`;
  }

  if (/^\d{2}-\d{2}-\d{4}$/.test(raw)) {
    return raw;
  }

  return raw;
}

function formatCurrency(value: number | string | null | undefined): string {
  const safeValue = Number(value ?? 0);
  return `₹${safeValue.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',')}`;
}

function toIndianWords(amount: number): string {
  const number = Math.round(Number(amount || 0));
  if (number === 0) {
    return 'Zero Rupees Only';
  }

  const ones = [
    '',
    'One',
    'Two',
    'Three',
    'Four',
    'Five',
    'Six',
    'Seven',
    'Eight',
    'Nine',
  ];
  const teens = [
    'Ten',
    'Eleven',
    'Twelve',
    'Thirteen',
    'Fourteen',
    'Fifteen',
    'Sixteen',
    'Seventeen',
    'Eighteen',
    'Nineteen',
  ];
  const tens = [
    '',
    '',
    'Twenty',
    'Thirty',
    'Forty',
    'Fifty',
    'Sixty',
    'Seventy',
    'Eighty',
    'Ninety',
  ];

  const convertUnderHundred = (value: number): string => {
    if (value < 10) {
      return ones[value];
    }
    if (value < 20) {
      return teens[value - 10];
    }
    if (value < 100) {
      const tensDigit = Math.floor(value / 10);
      const remainder = value % 10;
      return remainder
        ? `${tens[tensDigit]} ${ones[remainder]}`
        : tens[tensDigit];
    }
    return '';
  };

  const convertUnderThousand = (value: number): string => {
    if (value < 100) {
      return convertUnderHundred(value);
    }

    const hundreds = Math.floor(value / 100);
    const remainder = value % 100;
    const hundredText = `${ones[hundreds]} Hundred`;
    return remainder
      ? `${hundredText} ${convertUnderHundred(remainder)}`
      : hundredText;
  };

  const crore = Math.floor(number / 10000000);
  let remainderAfterCrore = number % 10000000;
  const lakh = Math.floor(remainderAfterCrore / 100000);
  remainderAfterCrore %= 100000;
  const thousand = Math.floor(remainderAfterCrore / 1000);
  remainderAfterCrore %= 1000;
  const hundred = Math.floor(remainderAfterCrore / 100);
  remainderAfterCrore %= 100;

  const parts: string[] = [];

  if (crore > 0) {
    parts.push(`${convertUnderThousand(crore)} Crore`);
  }

  if (lakh > 0) {
    parts.push(`${convertUnderThousand(lakh)} Lakh`);
  }

  if (thousand > 0) {
    parts.push(`${convertUnderThousand(thousand)} Thousand`);
  }

  if (hundred > 0) {
    parts.push(`${convertUnderThousand(hundred)} Hundred`);
  }

  if (remainderAfterCrore > 0) {
    parts.push(convertUnderHundred(remainderAfterCrore));
  }

  const finalWords = parts.filter(Boolean).join(' ');
  return `${finalWords || 'Zero'} Rupees Only`;
}

function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

const FIXED_INVOICE_ITEM_ROW_COUNT = 15;

type InvoiceItemRowsResult = {
  rowsHtml: string;
  truncatedItemCount: number;
};

function buildInvoiceItemRows(items: any[] = []): InvoiceItemRowsResult {
  const safeItems = Array.isArray(items) ? items : [];

  const truncatedItemCount = Math.max(
    0,
    safeItems.length - FIXED_INVOICE_ITEM_ROW_COUNT,
  );
  const visibleItems = safeItems.slice(0, FIXED_INVOICE_ITEM_ROW_COUNT);

  if (truncatedItemCount > 0) {
    console.warn(
      `Invoice PDF truncating ${truncatedItemCount} item(s); rendering first ${FIXED_INVOICE_ITEM_ROW_COUNT} rows.`,
    );
  }

  const rowsHtml = Array.from(
    {length: FIXED_INVOICE_ITEM_ROW_COUNT},
    (_, i) => {
      const item = visibleItems[i];

      if (!item) {
        return `
        <tr class="item-row">
          <td class="br text-center align-top pt-2">&nbsp;</td>
          <td class="br align-top pt-2 item-description-cell">&nbsp;</td>
          <td class="br text-center align-top pt-2">&nbsp;</td>
          <td class="br text-center align-top pt-2">&nbsp;</td>
          <td class="br text-center align-top pt-2">&nbsp;</td>
          <td class="br text-center align-top pt-2">&nbsp;</td>
          <td class="br text-right align-top pt-2">&nbsp;</td>
          <td class="br text-center align-top pt-2">&nbsp;</td>
          <td class="text-right align-top pt-2">&nbsp;</td>
        </tr>
      `;
      }

      const productName = escapeHtml(
        item.product_name || item.name || 'Product',
      );
      const hsn = escapeHtml(item.hsn_sac || item.hsn || '-');
      const gstRate = escapeHtml(item.gst_rate ?? item.gst ?? 0);
      const quantity = escapeHtml(item.quantity ?? 0);
      const unit = escapeHtml(item.unit || '');
      const rate = formatCurrency(item.price_incl_gst ?? item.unitprice ?? 0);
      const discount = escapeHtml(item.discount_percent ?? item.disc ?? 0);
      const taxableValue = formatCurrency(
        item.item_total_excl_gst ?? item.pregstprice ?? 0,
      );

      return `
        <tr class="item-row">
          <td class="br text-center align-top pt-2">${i + 1}</td>
          <td class="br align-top pt-2 item-description-cell">${productName}</td>
          <td class="br text-center align-top pt-2">${hsn}</td>
          <td class="br text-center align-top pt-2">${gstRate}</td>
          <td class="br text-center align-top pt-2">${quantity}</td>
          <td class="br text-center align-top pt-2">${unit}</td>
          <td class="br text-right align-top pt-2">${rate}</td>
          <td class="br text-center align-top pt-2">${discount}</td>
          <td class="text-right align-top pt-2">${taxableValue}</td>
        </tr>
      `;
    },
  ).join('');

  return {
    rowsHtml,
    truncatedItemCount,
  };
}

const INVOICE_ROW_MARKER_START =
  '<!-- START DYNAMIC PRODUCT ROW LOOP IN REACT NATIVE -->';
const INVOICE_ROW_MARKER_END = '<!-- END DYNAMIC PRODUCT ROW LOOP -->';

function loadInvoiceTemplate(): string {
  if (!INVOICE_TEMPLATE_HTML || typeof INVOICE_TEMPLATE_HTML !== 'string') {
    throw new Error('Invoice template is missing from the app bundle.');
  }

  return INVOICE_TEMPLATE_HTML;
}

function injectInvoiceRows(template: string, itemRowsHtml: string): string {
  if (!template || typeof template !== 'string') {
    throw new Error('Invoice template is missing or invalid.');
  }
  const rowPattern = new RegExp(
    `${escapeRegExp(INVOICE_ROW_MARKER_START)}[\\s\\S]*?${escapeRegExp(
      INVOICE_ROW_MARKER_END,
    )}`,
    'm',
  );

  const replacement = `${INVOICE_ROW_MARKER_START}\n${itemRowsHtml}\n${INVOICE_ROW_MARKER_END}`;

  return template.replace(rowPattern, replacement);
}

function applyTemplateValues(
  template: string,
  values: Record<string, string>,
): string {
  return Object.entries(values).reduce((html, [key, value]) => {
    const placeholder = `{{${key}}}`;
    return html.replace(new RegExp(escapeRegExp(placeholder), 'g'), value);
  }, template);
}

async function generateUpiQrDataUrl(amount: number): Promise<string> {
  const amountValue = Number(amount || 0);
  const upiPayload = `upi://pay?pa=${encodeURIComponent(
    UPI_VPA,
  )}&pn=${encodeURIComponent(UPI_NAME)}&am=${amountValue.toFixed(2)}&cu=INR`;
  const defaultImagePath = 'src/assets/upi-default.jpeg';

  try {
    const qrLib: any = QRCode;
    const svgMarkup = await qrLib.toString(upiPayload, {
      type: 'svg',
      errorCorrectionLevel: 'M',
      margin: 1,
      width: 300,
      color: {
        dark: '#000000',
        light: '#FFFFFF',
      },
    });

    return `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svgMarkup)}`;
  } catch (error) {
    console.warn('QR generation failed:', error);
    // return base 64 of src/assets/upi-default.jpeg by default
    const base64Data = await RNFS.readFile(defaultImagePath, 'base64').catch(
      () => '',
    );
    return `data:image/jpeg;base64,${base64Data}`;
  }
}

async function ensurePdfDirectory(): Promise<string> {
  const directory = `${RNFS.DocumentDirectoryPath}/${INVOICE_PDF_DIRECTORY}`;
  await RNFS.mkdir(directory);
  return directory;
}

const OCB_LOGO_DATA_URI =
  'data:image/png;base64,';

function loadLogoDataUri(): string {
  return OCB_LOGO_DATA_URI || '';
}

export async function generateInvoicePdfFromBill({
  bill,
  supplierConfig,
  billItems,
}: {
  bill: any;
  supplierConfig?: any;
  billItems?: any[];
}) {
  const invoiceNumber = safeString(bill?.invoice_number, '000');
  const invoiceSequenceValue = extractInvoiceSequenceNumber(invoiceNumber);
  const invoiceNumberToken = normalizeFileToken(
    invoiceSequenceValue || invoiceNumber,
    '000',
  );
  const invoiceKind = safeString(bill?.bill_kind || 'B2C', 'B2C').toUpperCase();
  const invoiceKindToken = normalizeFileToken(invoiceKind, 'B2C').toUpperCase();
  const dateValue = normalizeDisplayDate(
    bill?.date || new Date().toISOString(),
  );
  const placeOfSupplyState = getStateName(bill?.place_of_supply_state);
  const totalInclGst = Number(bill?.total_incl_gst ?? bill?.grand_total ?? 0);
  const totalExclGst = Number(bill?.total_excl_gst ?? bill?.total ?? 0);
  const cgst = Number(bill?.cgst_total ?? bill?.cgst ?? 0);
  const sgst = Number(bill?.sgst_total ?? bill?.sgst ?? 0);
  const igst = Number(bill?.igst_total ?? bill?.igst ?? 0);
  const roundOffAmount = totalExclGst + cgst + sgst + igst - totalInclGst;
  const qrDataUrl = await generateUpiQrDataUrl(totalInclGst);
  const logoDataUri = await loadLogoDataUri();
  const invoiceItems = billItems || bill?.billitems || [];
  const templateSource = loadInvoiceTemplate();
  const {rowsHtml, truncatedItemCount} = buildInvoiceItemRows(invoiceItems);
  const html = applyTemplateValues(
    injectInvoiceRows(templateSource, rowsHtml),
    {
      LOGO_IMAGE_DATA_URI: logoDataUri || '',
      INVOICE_NO: escapeHtml(invoiceNumber),
      INVOICE_DATE: escapeHtml(dateValue),
      PLACE_OF_SUPPLY: escapeHtml(placeOfSupplyState || ''),
      INVOICE_TYPE: escapeHtml(bill?.bill_kind || ''),
      BILLING_NAME: escapeHtml(bill?.customer_name || 'Customer Name'),
      BILLING_ADDRESS: escapeHtml(bill?.billing_address || ''),
      BILLING_GSTIN: escapeHtml(bill?.customer_gstin || ''),
      BILLING_PHONE: escapeHtml(bill?.customer_phone || ''),
      SHIPPING_ADDRESS: escapeHtml(bill?.shipping_address || ''),
      BANK_AC_NAME: escapeHtml(
        supplierConfig?.legal_business_name || 'OLGA CONCRETE BLOCKS',
      ),
      BANK_NAME: escapeHtml(supplierConfig?.business_name || 'Indian Bank'),
      BANK_BRANCH: escapeHtml(supplierConfig?.branch_name || 'Thycaud'),
      BANK_AC_NO: escapeHtml(supplierConfig?.account_number || '8347203408'),
      BANK_IFSC: escapeHtml(supplierConfig?.ifsc || 'IDIB000T021'),
      TOTAL_TAXABLE_VALUE: formatCurrency(totalExclGst),
      CGST_TOTAL: formatCurrency(cgst),
      SGST_TOTAL: formatCurrency(sgst),
      IGST_TOTAL: formatCurrency(igst),
      SUB_TOTAL: formatCurrency(totalExclGst + cgst + sgst + igst),
      ROUND_OFF_AMT: formatCurrency(roundOffAmount),
      GRAND_TOTAL: formatCurrency(totalInclGst),
      AMOUNT_IN_WORDS: escapeHtml(toIndianWords(totalInclGst)),
      UPI_QR_BASE64_URL: qrDataUrl || '',
      QR_DISPLAY_TOGGLE: qrDataUrl ? 'block' : 'none',
      QR_PLACEHOLDER_TOGGLE: qrDataUrl ? 'none' : 'block',
    },
  );

  const directoryPath = await ensurePdfDirectory();
  const safeFileName =
    `invoice_${invoiceKindToken}_${invoiceNumberToken}_${dateValue.replace(
      /\//g,
      '-',
    )}`.replace(/\s+/g, '_');
  const htmlToPdf = (RNHTMLtoPDF as any)?.generatePDF
    ? (RNHTMLtoPDF as any)
    : (RNHTMLtoPDF as any)?.default || null;

  if (!htmlToPdf || typeof htmlToPdf.generatePDF !== 'function') {
    throw new Error('HTML to PDF generator is not available in this runtime.');
  }

  const result = await htmlToPdf.generatePDF({
    html,
    fileName: safeFileName,
    directory: INVOICE_PDF_DIRECTORY,
    padding: 8,
  });

  if (!result?.filePath) {
    throw new Error('Invoice PDF generation failed.');
  }

  return {
    filePath: result.filePath,
    directoryPath,
    fileName: `${safeFileName}.pdf`,
    truncatedItemCount,
  };
}

export async function listSavedInvoicePdfs(): Promise<string[]> {
  const candidates = [
    `${RNFS.DocumentDirectoryPath}/${INVOICE_PDF_DIRECTORY}`,
    RNFS.DocumentDirectoryPath,
    RNFS.DownloadDirectoryPath,
    RNFS.ExternalDirectoryPath,
  ].filter(Boolean);

  const seen = new Set<string>();
  const files: string[] = [];

  for (const directoryPath of candidates) {
    try {
      const entries = await RNFS.readDir(directoryPath as string);
      for (const entry of entries) {
        const name = entry.name.toLowerCase();
        if (!entry.isFile() || !name.endsWith('.pdf')) {
          continue;
        }
        if (!name.startsWith('invoice_')) {
          continue;
        }

        const fullPath = `${directoryPath}/${entry.name}`;
        if (!seen.has(fullPath)) {
          seen.add(fullPath);
          files.push(fullPath);
        }
      }
    } catch (error) {
      // Ignore missing/unreadable directories and continue scanning.
    }
  }

  return files.sort((a, b) => b.localeCompare(a));
}

export function matchesInvoicePdfFilename(
  fileName: string,
  invoiceNumber: string | number,
): boolean {
  const normalizedFileName = (fileName || '').toLowerCase();
  const rawInvoiceNumber = safeString(invoiceNumber, '').toLowerCase();

  if (!normalizedFileName.startsWith('invoice_') || !rawInvoiceNumber) {
    return false;
  }

  const baseFileName = normalizedFileName.replace(/\.pdf$/i, '');
  const invoiceSequence = String(
    extractInvoiceSequenceNumber(rawInvoiceNumber),
  );
  const invoiceKindToken = rawInvoiceNumber.includes('b2b') ? 'b2b' : 'b2c';

  const directPattern = new RegExp(
    `(?:^|_)${escapeRegExp(
      normalizeFileToken(rawInvoiceNumber, '').toLowerCase(),
    )}(?:_|$)`,
  );
  if (directPattern.test(baseFileName)) {
    return true;
  }

  if (invoiceSequence && invoiceSequence !== '0') {
    const sequencePattern = new RegExp(
      `(?:^|_)${escapeRegExp(invoiceSequence)}(?:_|$)`,
    );
    const kindPattern = new RegExp(
      `(?:^|_)${escapeRegExp(invoiceKindToken)}(?:_|$)`,
    );

    if (sequencePattern.test(baseFileName)) {
      return true;
    }

    if (kindPattern.test(baseFileName) && sequencePattern.test(baseFileName)) {
      return true;
    }
  }

  return false;
}

export async function getSavedInvoicePdfPath(
  invoiceNumber: string | number,
): Promise<string | null> {
  const invoiceToken = normalizeFileToken(invoiceNumber, '').toLowerCase();

  if (!invoiceToken) {
    return null;
  }

  const pdfFiles = await listSavedInvoicePdfs();
  const match = pdfFiles.find(filePath => {
    const fileName = filePath.split('/').pop() || '';
    return matchesInvoicePdfFilename(fileName, invoiceNumber);
  });

  return match || null;
}

export async function openSavedInvoicePdf(filePath: string): Promise<void> {
  // FileViewer requires an absolute path WITHOUT file://
  const normalizedPath = filePath.startsWith('file://')
    ? filePath.replace(/^file:\/\//, '')
    : filePath;

  try {
    // 1. ADD showOpenWithDialog to prevent immediate MIME crashes on Android
    await FileViewer.open(normalizedPath, { showOpenWithDialog: true });
    return;
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    if (!message.toLowerCase().includes('mime type') && !message.toLowerCase().includes('no app associated')) {
      throw error;
    }
  }

  try {
    // 2. Use react-native-share, which natively supports Android file intents
    // This requires the file:// prefix to work correctly
    await RNShare.open({
      title: 'Invoice PDF',
      message: 'Open the generated invoice PDF.',
      url: `file://${normalizedPath}`, 
      type: 'application/pdf', 
    });
  } catch (shareError) {
    console.warn('Unable to open or share invoice PDF:', shareError);
    throw shareError;
  }
}
